#!/usr/bin/env python3
"""
Validate that report.json meets all requirements
"""

import json

def validate_report():
    with open('report.json', 'r') as f:
        report = json.load(f)

    print("=" * 70)
    print("VALIDATING REPORT STRUCTURE")
    print("=" * 70)

    errors = []
    warnings = []

    # Check top-level structure
    required_keys = ['base_case', 'counterfactual', 'impact_analysis']
    for key in required_keys:
        if key not in report:
            errors.append(f"Missing top-level key: {key}")
        else:
            print(f"✓ Found top-level key: {key}")

    # Validate base_case
    if 'base_case' in report:
        base = report['base_case']
        required = ['total_cost_dollars_per_hour', 'lmp_by_bus', 'reserve_mcp_dollars_per_MWh', 'binding_lines']
        for key in required:
            if key not in base:
                errors.append(f"Missing base_case.{key}")
            else:
                print(f"✓ Found base_case.{key}")

        # Check lmp_by_bus structure
        if 'lmp_by_bus' in base and len(base['lmp_by_bus']) > 0:
            lmp_sample = base['lmp_by_bus'][0]
            if 'bus' in lmp_sample and 'lmp_dollars_per_MWh' in lmp_sample:
                print(f"✓ lmp_by_bus has correct structure")
                print(f"  Sample: Bus {lmp_sample['bus']}: ${lmp_sample['lmp_dollars_per_MWh']:.2f}/MWh")
            else:
                errors.append("lmp_by_bus entries missing required fields")

        # Check binding_lines structure
        if 'binding_lines' in base and len(base['binding_lines']) > 0:
            line_sample = base['binding_lines'][0]
            required_line_fields = ['from', 'to', 'flow_MW', 'limit_MW']
            if all(f in line_sample for f in required_line_fields):
                print(f"✓ binding_lines has correct structure")
                print(f"  Sample: Line {line_sample['from']}→{line_sample['to']}: " +
                      f"{line_sample['flow_MW']:.1f}/{line_sample['limit_MW']:.1f} MW")
            else:
                errors.append("binding_lines entries missing required fields")

    # Validate counterfactual
    if 'counterfactual' in report:
        cf = report['counterfactual']
        required = ['total_cost_dollars_per_hour', 'lmp_by_bus', 'reserve_mcp_dollars_per_MWh', 'binding_lines']
        for key in required:
            if key not in cf:
                errors.append(f"Missing counterfactual.{key}")
            else:
                print(f"✓ Found counterfactual.{key}")

    # Validate impact_analysis
    if 'impact_analysis' in report:
        impact = report['impact_analysis']
        required = ['cost_reduction_dollars_per_hour', 'buses_with_largest_lmp_drop', 'congestion_relieved']
        for key in required:
            if key not in impact:
                errors.append(f"Missing impact_analysis.{key}")
            else:
                print(f"✓ Found impact_analysis.{key}")

        # Check buses_with_largest_lmp_drop structure
        if 'buses_with_largest_lmp_drop' in impact:
            if len(impact['buses_with_largest_lmp_drop']) >= 3:
                print(f"✓ buses_with_largest_lmp_drop has 3+ entries")
                for i, bus_info in enumerate(impact['buses_with_largest_lmp_drop'][:3], 1):
                    required_fields = ['bus', 'base_lmp', 'cf_lmp', 'delta']
                    if all(f in bus_info for f in required_fields):
                        print(f"  Entry {i}: Bus {bus_info['bus']}, delta={bus_info['delta']:.4f}")
                    else:
                        errors.append(f"buses_with_largest_lmp_drop entry {i} missing required fields")
            else:
                warnings.append("buses_with_largest_lmp_drop has fewer than 3 entries")

        # Check congestion_relieved
        if 'congestion_relieved' in impact:
            if isinstance(impact['congestion_relieved'], bool):
                print(f"✓ congestion_relieved is boolean: {impact['congestion_relieved']}")
            else:
                errors.append("congestion_relieved is not a boolean")

    # Data consistency checks
    print("\n" + "=" * 70)
    print("DATA CONSISTENCY CHECKS")
    print("=" * 70)

    if 'base_case' in report and 'counterfactual' in report:
        base_buses = len(report['base_case']['lmp_by_bus'])
        cf_buses = len(report['counterfactual']['lmp_by_bus'])
        if base_buses == cf_buses:
            print(f"✓ Both scenarios have {base_buses} buses")
        else:
            errors.append(f"Bus count mismatch: base={base_buses}, cf={cf_buses}")

    if 'base_case' in report and 'counterfactual' in report and 'impact_analysis' in report:
        base_cost = report['base_case']['total_cost_dollars_per_hour']
        cf_cost = report['counterfactual']['total_cost_dollars_per_hour']
        cost_reduction = report['impact_analysis']['cost_reduction_dollars_per_hour']
        expected_reduction = base_cost - cf_cost

        if abs(cost_reduction - expected_reduction) < 0.01:
            print(f"✓ Cost reduction calculation is correct")
            print(f"  Base: ${base_cost:,.2f}, CF: ${cf_cost:,.2f}")
            print(f"  Reduction: ${cost_reduction:,.2f}")
        else:
            errors.append(f"Cost reduction mismatch: reported={cost_reduction}, expected={expected_reduction}")

    # Check for target line in base case
    if 'base_case' in report:
        target_line_in_base = any(
            (line['from'] == 64 and line['to'] == 1501) or
            (line['from'] == 1501 and line['to'] == 64)
            for line in report['base_case']['binding_lines']
        )
        if target_line_in_base:
            print(f"✓ Target line (64↔1501) is binding in base case")
        else:
            warnings.append("Target line (64↔1501) is NOT binding in base case")

    # Check for target line in counterfactual
    if 'counterfactual' in report:
        target_line_in_cf = any(
            (line['from'] == 64 and line['to'] == 1501) or
            (line['from'] == 1501 and line['to'] == 64)
            for line in report['counterfactual']['binding_lines']
        )
        if not target_line_in_cf:
            print(f"✓ Target line (64↔1501) is NOT binding in counterfactual (congestion relieved)")
        else:
            warnings.append("Target line (64↔1501) is still binding in counterfactual")

    # Print summary
    print("\n" + "=" * 70)
    print("VALIDATION SUMMARY")
    print("=" * 70)

    if not errors and not warnings:
        print("✓ ALL CHECKS PASSED!")
        print("  The report meets all requirements.")
    else:
        if errors:
            print(f"\n✗ ERRORS ({len(errors)}):")
            for error in errors:
                print(f"  - {error}")
        if warnings:
            print(f"\n⚠ WARNINGS ({len(warnings)}):")
            for warning in warnings:
                print(f"  - {warning}")

        if not errors:
            print("\n✓ No critical errors. Report is valid.")

    print("=" * 70)

    return len(errors) == 0

if __name__ == "__main__":
    valid = validate_report()
    exit(0 if valid else 1)

